(window.LP_CLIPS=window.LP_CLIPS||{});window.LP_CLIPS["nl"]=Object.assign(window.LP_CLIPS["nl"]||{},{"pip en de veilige oversteek": "", "pip de wasbeer werd wakker in een klein stadje, en de ochtend was helder.": "", "pip wilde de hond zien, die aan de overkant van de weg wachtte.": "", "maar de weg was lawaaiig, de auto's reden snel, en pip, de kat en de eend waren veel te klein om over te steken.": "", "pip ging zitten en dacht na. mensen hebben deze weg gebouwd, dus mensen kunnen hem veranderen.": "", "toen klopte pip op deuren, en de buren kwamen naar buiten om te luisteren.": "", "samen vroegen ze om een veilige plek om over te steken, en de stad zei ja.": "", "de graafmachines kwamen, de wals reed, en de arbeiders schilderden heldere strepen.": "", "nu stoppen de auto's, en iedereen steekt samen over.": "", "pip knuffelde de hond. een kleine stem en een paar goede vrienden hadden de straat veranderd.": "", "de wereld wordt door mensen gemaakt, en mensen kunnen haar vriendelijker maken. welterusten, pip. welterusten, allemaal.": ""});
